head.script:
///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — 업종코드 목록 조회
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFILINDCODE.onpageload" });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name grd_list_oncellclick
 * @description grd_list 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_list_oncellclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.setParam(rowIndex);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFILINDCODE.grd_list_oncellclick" });
    }
};

/**
 * @method
 * @name btn_search_onclick
 * @description 「검색」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_search_onclick = async function (e) {
    try {
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFILINDCODE.btn_search_onclick" });
    }
};

/**
 * @method
 * @name ipb_keyword_onkeydown
 * @description ipb_keyword 키 입력 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipb_keyword_onkeydown = async function (e) {
    try {
        if(e.key === "Enter"){
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDFILINDCODE.ipb_keyword_onkeydown" });
    }
};

/**
 * @method
 * @name close_onclick
 * @description 「닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.close_onclick = function (e) {
    try {
        $c.win.closePopup();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFILINDCODE.close_onclick" });
    }
};

/**
 * @method
 * @name btn_confirm_onclick
 * @description 「확인」 버튼 — 선택 행을 오프너에 전달한다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_confirm_onclick = function (e) {
    try {
        scwin.setParam();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDFILINDCODE.btn_confirm_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 업종코드 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {

    dma_searchReq.set("indNm", ipb_keyword.getValue());

    const sbmOptions = {
        id : "sbm_List",
        method: "get",
        action : "/api/listing/common/pop/etc/select-list-industry",
        ref : "dma_searchReq",
        target : "dlt_res=body",
        gridview : "grd_list",
        isProcessMsg : false
    };
    await $c.sbm.executeDynamic(sbmOptions);

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name setParam
 * @description 선택된 값을 오프너에 전달한다.
 * @param {Number} v_Currow 행 인덱스(없으면 현재 선택 행)
 * @returns {void}
 * @hidden N
 */
scwin.setParam = function(v_Currow) {

    if (v_Currow === undefined) {
        v_Currow = dlt_res.getRowPosition();
    }

    const res = dlt_res.getRowJSON(v_Currow);
    $c.win.closePopup(res);
};
